INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('石硫合剂', '{"component":"石硫合剂","ph":"11.0-13.0（强碱性）","contraindications":"【作物限制】桃、李、杏、葡萄等敏感作物禁用；高温32℃以上不宜使用；萌芽后慎用\n【混配限制】不可与任何酸性农药混用；与波尔多液间隔至少15天；不可与有机磷农药混用"}', '2026-08-22T01:14:46.869Z');
